documents.scalar:
yamaa: "1.0"
type: spec
domain: TEST
keys: [ID]
input: {SRC: {path: input.csv, types: {I: int, F: float, D: date}}}
output: {path: output.csv, columns: [ID, RESULT]}
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: RESULT, type: str, derivation: {greatest: {sources: [SRC.I, SRC.F]}}}

files.spec.yaml:
yamaa: "1.0"
type: spec
domain: TEST
keys: [ID]
input: {SRC: {path: input.csv, types: {I: int, F: float}}}
output: {path: output.csv, columns: [ID, RESULT, MAXIMUM]}
columns:
  - {name: ID, type: str}
  - {name: RESULT, type: str}
  - {name: MAXIMUM, type: int}
rows:
  - id: values
    derivations:
      ID: SRC.ID
      RESULT: {str_template: '[{SRC.TEXT}]'}
      MAXIMUM: {greatest: {sources: [SRC.I, SRC.F]}}
